    def check_m67_roadmap_currentness(self, criterion: FoundationGateCriterion) -> FoundationGateResult:
        required_docs = [
            "README.md",
            "VERSION.md",
            "docs/canonical/09_roadmap.md",
            "docs/roadmap/M61_M100_ROADMAP.md",
            "docs/roadmap/POST_M20_CAPABILITY_LAYER_ROADMAP.md",
            "docs/roadmap/MILESTONE_CHARTERS.md",
        ]
        failures = [
            f"missing M67 roadmap doc: {path}"
            for path in required_docs
            if not (self.root / path).exists()
        ]
        text = "\n".join(
            self._read(self.root / path).lower()
            for path in required_docs
            if (self.root / path).exists()
        )
        if "v0.71.0" not in text or "m67" not in text or "revocation + kill switch" not in text:
            failures.append("active docs do not identify v0.71.0/M67 Revocation + Kill Switch")
        if "m67 is implemented/released" not in text and "v0.71.0 implements m67" not in text:
            failures.append("active docs do not mark M67 implemented/released")
        for version_label, milestone, title in [
            ("v0.72.0", "M68", "Autonomy Risk Classifier"),
            ("v0.73.0", "M69", "Low-Risk Autonomous Dry Run"),
            ("v0.74.0", "M70", "Autonomy Foundation Freeze"),
            ("v0.80.0", "M76", "OpenWebUI Runtime Bridge v1"),
            ("v0.94.0", "M90", "Shell/Subprocess Hardening Freeze"),
            ("v0.95.0", "M91", "Autonomous Tool Execution Contract"),
            ("v1.4.0", "M100", "Mobile Permission Model v1"),
        ]:
            if version_label.lower() not in text or milestone.lower() not in text or title.lower() not in text:
                failures.append(f"active docs missing planned M67-M100 row: {version_label} / {milestone} — {title}")
        for fragment in (
            "production authority is implemented",
            "broad autonomy is implemented",
            "tool execution is implemented",
            "shell execution is implemented",
            "browser automation is implemented",
        ):
            if fragment in text:
                failures.append(f"M67 docs imply forbidden/future capability: {fragment}")
        return self._result(criterion, failures, required_docs)

