    def check_m101_roadmap_currentness(self, criterion: FoundationGateCriterion) -> FoundationGateResult:
        required_docs = [
            "README.md",
            "VERSION.md",
            "docs/canonical/09_roadmap.md",
            "docs/roadmap/M101_M150_CAPABILITY_CHARTERS.md",
            "docs/roadmap/MILESTONE_CHARTERS.md",
            "docs/roadmap/POST_M20_CAPABILITY_LAYER_ROADMAP.md",
        ]
        failures = [
            f"missing M101 roadmap doc: {path}"
            for path in required_docs
            if not (self.root / path).exists()
        ]
        text = "\n".join(
            self._read(self.root / path).lower()
            for path in required_docs
            if (self.root / path).exists()
        )
        if "v1.5.0" not in text or "m101" not in text or "mobile sensor contract review" not in text:
            failures.append("active docs do not identify v1.5.0/M101 Mobile Sensor Contract Review")
        if "m101 is implemented/released" not in text and "v1.5.0 implements m101" not in text:
            failures.append("active docs do not mark M101 implemented/released")
        m102_implemented = "v1.6.0" in text and "m102" in text
        m103_implemented = "v1.7.0" in text and "m103" in text
        planned_rows = [
            ("v1.2.0-alpha", "alpha", "m150", "ultimate ai agent v1.2.0-alpha"),
        ]
        if not m103_implemented:
            planned_rows.insert(
                0,
                ("v1.7.0", "pre-alpha internal", "m103", "camera/photos metadata-only contract"),
            )
        if not m102_implemented:
            planned_rows.insert(
                0,
                ("v1.6.0", "pre-alpha internal", "m102", "location sensor, off by default"),
            )
        for version_label, product_target, milestone, title in planned_rows:
            row = (
                f"| {version_label} | {product_target} | {milestone} | "
                f"{title} | planned/provisional |"
            )
            if not _roadmap_row_present(text, row):
                failures.append(
                    f"active docs missing planned M102-M150 row: {version_label} / {milestone.upper()} - {title}"
                )
        forbidden_fragments = [
            "location sensor runtime is implemented",
            "native permission prompt is implemented",
            "background collection is implemented",
            "production authority is implemented",
            "broad autonomy is implemented",
        ]
        if not m102_implemented:
            forbidden_fragments.extend(["m102 is implemented", "v1.6.0 implements m102"])
        if not m103_implemented:
            forbidden_fragments.extend(["m103 is implemented", "v1.7.0 implements m103"])
        for fragment in forbidden_fragments:
            if fragment in text:
                failures.append(f"M101 docs imply forbidden/future capability: {fragment}")
        return self._result(criterion, failures, required_docs)

