            "contract-only",
            "review-only",
            "safe refs",
            "threat surface refs",
            "mitigation plan refs",
            "mobile sensor hardening freeze",
            "actor-bound",
            "baseline-bound",
            "source-freeze-bound",
            "audit",
            "replay",
            "no-effect receipt plan",
            "no production authority",
            "no production runtime",
            "no external distribution",
            "no deployment",
            "no credential handling",
            "no network access",
            "no model call",
            "no memory write",
            "no context injection",
            "no execution",
