            "review-only",
            "safe refs",
            "remote agent coordination contract",
            "deployment mode refs",
            "environment refs",
            "authority tier refs",
            "rollout stage refs",
            "rollback boundary ref",
            "actor-bound",
            "baseline-bound",
            "source-remote-agent-coordination-bound",
