            "no autonomous recovery execution",
            "no retry execution",
            "no rollback execution",
            "no resume execution",
            "no dependency execution",
            "no browser action",
            "no connector action",
            "no tool execution",
            "no shell execution",
            "no network access",
            "no plugin execution",
